'use client';

import { type PropsWithChildren, useRef } from 'react';

type GlareHoverProps = PropsWithChildren<{ className?: string; reducedMotion: boolean }>;

/** Dependency-free adaptation of React Bits' Glare Hover. */
export function GlareHover({ children, className = '', reducedMotion }: GlareHoverProps) {
  const elementRef = useRef<HTMLDivElement>(null);
  const handlePointerMove: React.PointerEventHandler<HTMLDivElement> = (event) => {
    if (reducedMotion || event.pointerType !== 'mouse' || !elementRef.current) return;
    const bounds = elementRef.current.getBoundingClientRect();
    elementRef.current.style.setProperty('--glare-x', `${((event.clientX - bounds.left) / bounds.width) * 100}%`);
    elementRef.current.style.setProperty('--glare-y', `${((event.clientY - bounds.top) / bounds.height) * 100}%`);
  };
  return <div ref={elementRef} className={`glare-hover${reducedMotion ? ' glare-hover-static' : ''} ${className}`} onPointerMove={handlePointerMove}>{children}</div>;
}
