type ShinyTextProps = { children: string; reducedMotion: boolean; className?: string };

/** CSS-only adaptation of React Bits' Shiny Text. */
export function ShinyText({ children, reducedMotion, className = '' }: ShinyTextProps) {
  return <span className={`shiny-text${reducedMotion ? ' shiny-text-static' : ''} ${className}`}>{children}</span>;
}
